LL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://www.toegankelijkgebouw.be/Handboek/Niveauverschillen/Helling/tabid/256/Default.aspx', '2026-09-17', NULL, NULL, 5, 'national_fw', 'BE', NULL, NULL, NULL, 'COMPLETE', 'VERIFIED', 'NO-MATCH', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, '2026-09-17 21:51', 'session_2026-09-17-research-batch-12-acceptability-criterion', '2026-09-17 21:51', 'session_2026-09-17-research-batch-12-acceptability-criterion', 'retrieval-log', NULL, 1, NULL, 'Handboek › Niveauverschillen › Helling — Verhouding percentage-hoogteoverbrugging-lengte', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'intrinsic', 'captured', 'pending', NULL, NULL, NULL, NULL, 'CLOSED', 'tool', NULL);

-- search_executions: 2 insert(s), 0 update(s)
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation") VALUES (52, 'accessible-circulation-geometry', 'BE', 'nl', 5, 'national_fw', 'intrinsic', '"fysieke haalbaarheid" "rolstoelgebruiker" helling uitgangspunt toegankelijkheid Vlaanderen', NULL, 'web', 'scoping', NULL, 9, 9, 1, NULL, NULL, NULL, 0, 'session_2026-09-17-research-batch-12-acceptability-criterion', '2026-09-17 21:52', 'PRIOR RIGHT THAT IT EXISTS, WRONG ON WHERE IT LIVES AND WRONG THAT IT IS BARE. LOCATION: the Regelgeving/Verduidelijking-bij-art-19 page carries only the decree explanatory memorandum and contains fysieke haalbaarheid ZERO times — retrieved and persisted, so the negative is evidenced. The criterion is on the Handboek proper, Handboek/Niveauverschillen/Helling, and is contiguous in those bytes. NOT BARE: the sentence before it states the MECHANISM — hoe groter het hoogteverschil, hoe zachter de helling moet zijn, omdat men gedurende een langere tijd een inspanning moet leveren — which is a dose-response argument in prose and runs in the same direction the two admitted studies measure. The sentence after fixes the design case as the SELF-PROPELLING wheelchair user, naming assistants, prams, trolleys and rollators as the reference rather than the criterion. So the corpus gains a criterion, a mechanism and a named design case where it expected one unsupported sentence. WHY THIS MATTERS BEYOND THE CELL: every other row for this parameter is a ceiling with no stated warrant. This is the first statement of what the number is FOR. It also supplies the term that stops the regress the owner statement of 2026-09-16 identified — monotonic dose-response curves with no plateau resolve to 0 degrees, which is not a ramp — because feasibility is about effort SUSTAINED over the run, so the acceptable gradient falls as the run lengthens rather than tending to zero. STILL NOT EVIDENCE OF THE STRONG KIND, and the record says so: a Flemish public agency asserting what wheelchair users can manage, with no participants, no measurement and no citation. Not Co-1. Tier: national_fw/T5 rather than grey/T3, deliberately — the 2026-09-13 ruling puts value-restating grey in the regulatory stratum, and T3 would let a handbook anchor more strongly than the decree it explains.', 0, 'Candidate 79, deferred twice and named in batch 11 own record as the highest-value target left. The criterion was staged from the Handboek by an earlier batch but never retrieved to a carrier. Prediction: the criterion is real and is on the Handboek Regelgeving page that batch 10 plan pointed at, and it states an acceptability principle with NO number and NO warrant behind it — a bare assertion that wheelchair-user feasibility is the basis, with nothing supporting it.');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation") VALUES (53, 'accessible-circulation-geometry', 'BE', 'nl', 1, 'co1', 'intrinsic', 'ervaringsdeskundige rolstoelgebruiker helling te steil ervaring gebruikersorganisatie Vlaanderen toegankelijkheid', NULL, 'web', 'scoping', NULL, 9, 9, 0, NULL, NULL, NULL, 0, 'session_2026-09-17-research-batch-12-acceptability-criterion', '2026-09-17 21:53', 'PRIOR CONFIRMED, AND THE PATTERN IS NOW FOUR FOR FOUR. The strongest lived-experience result (BRUZZ, retrieved and persisted, HTTP 200) is about ramp PROVISION: helling occurs twice, both about installing ramps at all; steil occurs ZERO times; no percentage or ratio appears anywhere. Its central testimony is a restaurateur saying wheelchair users do not come here, answered with maar ze kunnen niet — they cannot. That is a real access finding and it is not about gradient. NOTHING ADMITTED. R14: GENUINE ABSENCE of gradient content in the lived-experience material reached, query well formed and in-language. THE FOUR-FOR-FOUR PATTERN IS ITSELF THE RESULT. Across batches 10-12 the Co-1 leg has now been run against DPI Japan, PVA, APF France Handicap and Flemish lived-experience media. Every one produced material about whether access exists, is enforced, or is adequate as a whole; NOT ONE stated a gradient figure or a gradient threshold. Meanwhile four regulators and one sports federation state gradients freely, and the only criterion of acceptability the corpus holds (REF-00996) is a government agency speaking ON BEHALF of wheelchair users. THAT ASYMMETRY IS A FINDING ABOUT THE EVIDENCE BASE, not a gap in the searching: the people the parameter is FOR are published on whether they can get in, and the people who set the number are published on what the number is. Recorded here so a later reader does not mistake four well-formed zeroes for insufficient effort.', 0, 'Motivated by what this batch just admitted, not by the gate. REF-00996 is a government agency asserting what a self-propelling wheelchair user can physically manage. The obvious question is whether disabled people themselves say the same thing about gradient, in the same jurisdiction. Prediction: Flemish lived-experience material exists on accessibility generally but addresses ramp PROVISION — whether a ramp is there at all — rather than gradient, because the gradient question only arises once a ramp exists.');

-- evidence_population_match: 1 insert(s), 0 update(s)
INSERT INTO "evidence_population_match" ("match_id", "source_ref", "target_population", "study_population", "sample_size", "match_grade", "mismatch_note", "created_at", "created_by_session", "ref_id", "gap_id") VALUES ('session_2026-09-17-resea-REF-00996-MOB', 'REF-00996', 'MOB', 'No study population — a public accessibility agency stating a design criterion', NULL, 'PROXY', 'PROXY. The source names its design case precisely — de (zelfstandige) rolstoelgebruiker, the independently self-propelling wheelchair user — which is a tighter fit to MOB than any other regulatory row in this cell, and the reason device_class is recorded as manual_self_propelled rather than not_device_scoped. It is still PROXY and not EXACT because nobody was studied: a Flemish public agency is asserting what that user can physically manage, with no participants, no measurement and no citation. The gap between naming a population accurately and having evidence about it is exactly what this grade exists to keep visible.', '2026-09-17 21:52', 'session_2026-09-17-research-batch-12-acceptability-criterion', 'REF-00996', NULL);

