-- observed_terms: 4 insert(s), 0 update(s)
INSERT INTO "observed_terms" ("observation_id", "ref_id", "surface_form", "language", "locator", "context_quote", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (20, 'REF-00996', 'fysieke haalbaarheid', 'NL', 'Handboek › Niveauverschillen › Helling', 'Bij hellingen vormt de fysieke haalbaarheid van de (zelfstandige) rolstoelgebruiker het uitgangspunt.', 'PHYSICAL FEASIBILITY. The concept this corpus has been missing a name for: the property a gradient must have to be acceptable, as distinct from the number itself. Harvested verbatim and unjudged (D-0173); whether it maps to our threshold-of-acceptability notion is judgment work, not evidence work.', '2026-09-17 21:52', 'session_2026-09-17-research-batch-12-acceptability-criterion', '2026-09-17 21:52', 'session_2026-09-17-research-batch-12-acceptability-criterion');
INSERT INTO "observed_terms" ("observation_id", "ref_id", "surface_form", "language", "locator", "context_quote", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (21, 'REF-00996', 'zelfstandige rolstoelgebruiker', 'NL', 'Handboek › Niveauverschillen › Helling', 'Bij hellingen vormt de fysieke haalbaarheid van de (zelfstandige) rolstoelgebruiker het uitgangspunt.', 'The INDEPENDENT (self-propelling) wheelchair user, named as the design case. The parenthesis is the source own. Note what it excludes: the source treats an assisted user as the reference rather than the criterion, which is a substantive position about whose capability sets the standard.', '2026-09-17 21:52', 'session_2026-09-17-research-batch-12-acceptability-criterion', '2026-09-17 21:52', 'session_2026-09-17-research-batch-12-acceptability-criterion');
INSERT INTO "observed_terms" ("observation_id", "ref_id", "surface_form", "language", "locator", "context_quote", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (22, 'REF-00996', 'uitgangspunt', 'NL', 'Handboek › Niveauverschillen › Helling', 'Bij hellingen vormt de fysieke haalbaarheid van de (zelfstandige) rolstoelgebruiker het uitgangspunt.', 'STARTING POINT / point of departure. The speech act matters: the source does not say feasibility is a constraint to be satisfied, it says feasibility is what the whole rule is derived FROM. No other source in this cell makes a claim of that shape about its own figures.', '2026-09-17 21:52', 'session_2026-09-17-research-batch-12-acceptability-criterion', '2026-09-17 21:52', 'session_2026-09-17-research-batch-12-acceptability-criterion');
INSERT INTO "observed_terms" ("observation_id", "ref_id", "surface_form", "language", "locator", "context_quote", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (23, 'REF-00996', 'hellend vlak', 'NL', 'Handboek › Niveauverschillen › Helling', 'Een korte helling wordt vaak hellend vlak genoemd. Deze kunnen een steiler percentage hebben aangezien ze een beperkte inspanning vragen.', 'The source distinguishes a short INCLINED PLANE from a ramp proper and permits it a steeper percentage, on the stated ground that it demands limited effort. That is the same short-rise-buys-steeper structure as the Japanese 1:8 proviso and the Flemish 10% band — here with its rationale attached rather than bare.', '2026-09-17 21:52', 'session_2026-09-17-research-batch-12-acceptability-criterion', '2026-09-17 21:52', 'session_2026-09-17-research-batch-12-acceptability-criterion');

