-- search_candidates: 1 insert(s), 1 update(s)
INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "created_by_session", "created_at") VALUES (83, NULL, 'accessible-circulation-geometry', NULL, 'PENDING-VERIFICATION', 'Ramp Up Iceland / Ramp Up Reykjavík (Haraldur Thorleifsson)', NULL, 'UNVERIFIED', 1, 0, 'Surfaced in the BRUZZ piece as a disabled-founded project that has installed several hundred permanent ramps and now advises European cities. Not retrieved this pass; its own publications were not reached.', 'THE BEST REMAINING CO-1 PROSPECT FOR THIS PARAMETER, and it is a different KIND of prospect from the four DPOs already tried. Those publish positions; this one BUILDS RAMPS AT SCALE and is led by a wheelchair user. An organisation that has installed hundreds of ramps has had to decide a gradient hundreds of times, so if it publishes a design standard that is lived-experience authority attached to a number — the exact thing four Co-1 passes have failed to find.', 'session_2026-09-17-research-batch-12-acceptability-criterion', '2026-09-17 21:53');
UPDATE "search_candidates" SET "disposition" = 'ADMITTED', "notes" = 'THE HIGHEST-VALUE SINGLE TARGET LEFT IN THIS CELL. Every figure this corpus holds is a ceiling asserted without warrant. This sentence is the only statement met so far that frames the threshold on what a wheelchair user can PHYSICALLY DO independently — which is the owner question of 2026-09-16, almost verbatim. Candidate 69 resolved the table half against REF-00995 and left this half open. || RESOLVED 2026-09-17 (R15, re-described from the source; admitted as REF-00996): RESOLVED. The criterion is real, is where the candidate said it was, and reads exactly as staged: "Bij hellingen vormt de fysieke haalbaarheid van de (zelfstandige) rolstoelgebruiker het uitgangspunt." Verified as a contiguous substring of the persisted bytes, not reconstructed. TWO CORRECTIONS TO THE STAGED HYPOTHESIS. (1) The page is NOT the one candidate 69 and the batch-10 plan pointed at. The Regelgeving/Verduidelijking-bij-art-19 page carries only the decree explanatory memorandum and contains fysieke haalbaarheid ZERO times; the criterion lives on the Handboek proper, Handboek/Niveauverschillen/Helling. Both were retrieved and persisted, so the negative is evidenced rather than asserted. (2) The candidate staged the criterion alone; the source carries MORE than was staged. The sentence immediately before it gives the MECHANISM — hoe groter het hoogteverschil, hoe zachter de helling moet zijn, omdat men gedurende een langere tijd een inspanning moet leveren — and the sentence immediately after names an assistant, pram-pusher, trolley or rollator user as the REFERENCE rather than the criterion, which fixes the design case as the self-propelling wheelchair user. Both are filed as their own extractions; a re-description that recorded only the staged sentence would have lost the part that matters most.' WHERE "candidate_id" = 79;

