-- source_value_extractions: 2 insert(s), 0 update(s)
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (31, 'REF-00996', 'accessible-circulation-geometry', 3, 'MOB', NULL, NULL, NULL, 'BE', NULL, 'qualitative', 'physical feasibility for the independent wheelchair user is the starting point', NULL, 'Bij hellingen vormt de fysieke haalbaarheid van de (zelfstandige) rolstoelgebruiker het uitgangspunt.', 'Handboek › Niveauverschillen › Helling — Verhouding percentage-hoogteoverbrugging-lengte', NULL, 'committee_assertion', 'REF-00996', NULL, 'stated_unmeasured', 'manual_self_propelled', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'full-read', 'verified', NULL, 'THE CRITERION OF ACCEPTABILITY, AND THE ONLY ONE THIS CORPUS HOLDS. Every other row for this parameter is a ceiling asserted with no warrant: the ADA, the Japanese order, AD M, the Flemish decree and the IPC guide all state a number and none says what makes it acceptable. This sentence says what the number is FOR — the physical feasibility of the (independent) wheelchair user — and it is the owner question of 2026-09-16 almost verbatim. It supplies NO value, and is first-class evidence anyway under the 2026-09-13 ruling; figure_role=finding for that reason. device_class=manual_self_propelled is from the source itself, not inferred: zelfstandige rolstoelgebruiker is a self-propelling wheelchair user, and the sentence immediately after names assistant, pram, trolley and rollator as the REFERENCE rather than the criterion, so the design case is explicitly the person propelling themselves. THE CRITERION IS RULED BY A GOVERNMENT AGENCY, NOT BY DISABLED PEOPLE. Inter and Gelijke Kansen in Vlaanderen are Flemish public bodies, so this is a regulator stating what wheelchair users can manage, not wheelchair users saying so. It is the best-warranted statement in the cell and it is still not Co-1.', '2026-09-17 21:51', 'session_2026-09-17-research-batch-12-acceptability-criterion', '2026-09-17 21:51', 'session_2026-09-17-research-batch-12-acceptability-criterion', 'finding', NULL);
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (32, 'REF-00996', 'accessible-circulation-geometry', 3, 'MOB', NULL, NULL, NULL, 'BE', NULL, 'qualitative', 'sustained effort over longer ramps requires a gentler gradient', NULL, 'Hoe groter het hoogteverschil, hoe zachter (kleiner hellingspercentage) de helling moet zijn, omdat men gedurende een langere tijd een inspanning moet leveren, en het dus voor iedereen haalbaar moet blijven de volledige helling te nemen.', 'Handboek › Niveauverschillen › Helling — Verhouding percentage-hoogteoverbrugging-lengte', NULL, 'committee_assertion', 'REF-00996', NULL, 'stated_unmeasured', 'manual_self_propelled', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'full-read', 'verified', NULL, 'THE MECHANISM BEHIND THE RISE-CONDITIONED SHAPE, STATED OUT LOUD. Batch 11 found three incompatible rule shapes — flat (US/JP), going-conditioned (GB), rise-conditioned (BE-VL) — and could say what each does but not why. This says why the Flemish one is built that way: a greater height means effort sustained for LONGER, so the gradient must fall for the whole ramp to stay feasible. That is a dose-response argument in prose, and it is the same direction the two admitted dose-response studies measure. IT IS ALSO THE MISSING LINK THE OWNER STATEMENT OF 2026-09-16 NAMES. That statement allows dose-response evidence to be reasoned toward a range as a proxy, and warns that monotonic curves with no plateau resolve to 0 degrees, which is not a ramp. This supplies the term that stops the regress: feasibility is not about instantaneous effort but about SUSTAINED effort over the whole run, so the acceptable gradient falls as the run lengthens rather than tending to zero. Still an assertion — no measurement, no citation, no participants — so figure_role=finding and root_type=committee_assertion.', '2026-09-17 21:51', 'session_2026-09-17-research-batch-12-acceptability-criterion', '2026-09-17 21:51', 'session_2026-09-17-research-batch-12-acceptability-criterion', 'finding', NULL);